//! Closure-backed inline templates and the byte-to-text rendering bridge.

use std::{fmt, io};

use crate::Slice;

/// A reusable template generated by [`crate::html!`].
///
/// The closure owns its captures and is evaluated on every render. This type
/// implements [`Slice`] for composition with existing runtime APIs; it does
/// not imply automatic partial or layout handling.
pub struct InlineSlice<F> {
    render: F,
}

impl<F> InlineSlice<F>
where
    F: Fn(&mut dyn io::Write) -> io::Result<()>,
{
    /// Constructs a template renderer. Usually called by [`crate::html!`].
    pub fn new(render: F) -> Self {
        Self { render }
    }

    /// Writes directly to a byte destination without buffering the template.
    ///
    /// Returns the original I/O error, including errors from custom
    /// [`crate::WriteHtmlValue`] implementations. Does not flush the destination.
    /// The [`Slice::render`] text interface can only return [`fmt::Error`].
    pub fn write_to(&self, writer: &mut dyn io::Write) -> io::Result<()> {
        (self.render)(writer)
    }
}

impl<F> Slice for InlineSlice<F>
where
    F: Fn(&mut dyn io::Write) -> io::Result<()>,
{
    fn render_to_writer(&self, writer: &mut dyn io::Write) -> io::Result<()> {
        self.write_to(writer)
    }

    fn render(&self, writer: &mut dyn fmt::Write) -> fmt::Result {
        let mut adapter = TextWriter {
            writer,
            pending: [0; 4],
            len: 0,
        };
        self.write_to(&mut adapter).map_err(|_| fmt::Error)?;
        adapter.finish().map_err(|_| fmt::Error)
    }
}

/// Decodes UTF-8 incrementally, including code points split across byte writes.
struct TextWriter<'a> {
    writer: &'a mut dyn fmt::Write,
    pending: [u8; 4],
    len: usize,
}

impl TextWriter<'_> {
    fn finish(&self) -> io::Result<()> {
        if self.len == 0 {
            Ok(())
        } else {
            Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "incomplete UTF-8",
            ))
        }
    }

    fn text(&mut self, text: &str) -> io::Result<()> {
        self.writer.write_str(text).map_err(io::Error::other)
    }
}

impl io::Write for TextWriter<'_> {
    fn write(&mut self, mut bytes: &[u8]) -> io::Result<usize> {
        let length = bytes.len();
        while self.len != 0 && !bytes.is_empty() {
            self.pending[self.len] = bytes[0];
            self.len += 1;
            bytes = &bytes[1..];
            match std::str::from_utf8(&self.pending[..self.len]) {
                Ok(text) => {
                    // Do not replay a completed code point if the sink rejects it.
                    self.len = 0;
                    self.writer.write_str(text).map_err(io::Error::other)?;
                }
                Err(error) if error.error_len().is_some() => {
                    self.len = 0;
                    return Err(io::Error::new(io::ErrorKind::InvalidData, error));
                }
                Err(_) => {}
            }
        }
        if !bytes.is_empty() {
            match std::str::from_utf8(bytes) {
                Ok(text) => self.text(text)?,
                Err(error) => {
                    let (valid, rest) = bytes.split_at(error.valid_up_to());
                    self.text(std::str::from_utf8(valid).expect("validated prefix"))?;
                    if error.error_len().is_some() {
                        return Err(io::Error::new(io::ErrorKind::InvalidData, error));
                    }
                    self.pending[..rest.len()].copy_from_slice(rest);
                    self.len = rest.len();
                }
            }
        }
        Ok(length)
    }

    fn flush(&mut self) -> io::Result<()> {
        self.finish()
    }
}
